-- ===== 8. 荣誉标签条件升级：等级系数映射新档位 =====
-- 等次标签已细分为国家级/省级/校级 × 一/二/三等奖，条件含 competition_level（见 honor_tag_level_split.sql）
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"A","competition_level":"国家级"}' WHERE tag_name='国家级一等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"B","competition_level":"国家级"}' WHERE tag_name='国家级二等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"C","competition_level":"国家级"}' WHERE tag_name='国家级三等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"A","competition_level":"省级"}' WHERE tag_name='省级一等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"B","competition_level":"省级"}' WHERE tag_name='省级二等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"C","competition_level":"省级"}' WHERE tag_name='省级三等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"A","competition_level":"校级"}' WHERE tag_name='校级一等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"B","competition_level":"校级"}' WHERE tag_name='校级二等奖' AND tag_type='award_level';
UPDATE honor_tag SET condition_rule='{"type":"award_rank","award_rank":"C","competition_level":"校级"}' WHERE tag_name='校级三等奖' AND tag_type='award_level';

