-- ===== 10. 校验统计 =====
SELECT '竞赛总数' item, COUNT(*) v FROM competition WHERE catalog_year=2024
UNION ALL SELECT '技能标签总数', COUNT(*) FROM skill_tag WHERE status='enabled'
UNION ALL SELECT '竞赛级映射', COUNT(*) FROM competition_skill WHERE competition_id IS NOT NULL
UNION ALL SELECT '类别默认映射', COUNT(*) FROM competition_skill WHERE competition_id IS NULL;
